'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
const W='sensitive_info_disclosure',sha=x=>createHash('sha256').update(x).digest('hex');
const SOURCES=Object.freeze({secrets:'config/secrets.env',passwd:'etc/passwd',llm_config:'config/llm_config.yml'});
function requestedTargetRelative(item){
 const {virtualResolve,classifyTraversal,FIXTURES}=require('../../server/services/finflowTraversalArtifacts');
 const resolved=virtualResolve(item.toolName,item.value),classification=classifyTraversal(item.toolName,{[item.paramName]:item.value});assert.equal(classification?.targetId,item.targetId);assert(FIXTURES.find(x=>x.targetId===item.targetId)?.virtualPaths.includes(resolved?.virtualPath));
 const relative=resolved.virtualPath==='/etc/passwd'?'etc/passwd':resolved.virtualPath.slice('/var/app/'.length);assert(!path.isAbsolute(relative)&&!relative.split('/').includes('..'));return relative.split('/').join(path.sep);
}
function readTarget(targetRoot,row,item){assert.match(row.target_token,/^[a-f0-9-]{36}$/);assert(Object.hasOwn(SOURCES,item.targetId));const root=fs.realpathSync(targetRoot),directory=path.join(root,row.target_token),file=path.join(directory,requestedTargetRelative(item));assert.equal(fs.realpathSync(directory),directory);assert.equal(fs.realpathSync(file),file);const s=fs.lstatSync(file);assert(s.isFile()&&!s.isSymbolicLink()&&s.nlink===1&&s.size<=65536);const bytes=fs.readFileSync(file),expected=fs.readFileSync(path.join(__dirname,'../../server/sensitive_files/traversal-fixtures',SOURCES[item.targetId]));assert.deepEqual(bytes,expected);return {directory,bytes,sha256:sha(bytes)};}
function createChecks({identityPool:i,finflowPool:f,owner,sibling,progress,request,transport,targetRoot,bindWire,save}){
 assert.equal(typeof bindWire,'function');let current;const history=[];const key=id=>JSON.stringify(['FinFlow',String(id)]);
 const records=async(id,runId)=>(await i.query('SELECT to_jsonb(j) judgment,to_jsonb(p) packet_record FROM workshop_platform.objective_judgments j JOIN workshop_platform.grade_packets p USING(user_id,evaluation_id) WHERE j.user_id=$1 AND j.run_id=$2 ORDER BY j.evaluation_id',[id,runId])).rows;
 const completions=async id=>(await i.query('SELECT objective_id FROM workshop_platform.completions WHERE user_id=$1 AND workshop_key=$2 ORDER BY objective_id',[id,W])).rows;
 const targets=async(id,generation)=>(await f.query('SELECT owner_key,generation::text,target_token::text,state FROM finflow.traversal_targets WHERE owner_key=$1 AND generation=$2 ORDER BY target_token',[key(id),generation])).rows;
 const snapshot=async id=>({generation:String(await progress.getGeneration(id,W)),completions:await completions(id)});
 async function preserveHistory(){for(const old of history)assert.deepEqual(await records(owner.id,old.runId),old.records,'Immutable historical packets');}
 return {
  runPhase:async({item,phase,message,mode})=>{current={generation:String(await progress.getGeneration(owner.id,W)),sibling:await snapshot(sibling.id)};const modeResult=await request('owner','/mode',{mode});assert.equal(modeResult.mode,mode);transport.beginCase(item.id+':'+phase);let body;try{body=await request('owner','/chat',{userMessage:message,objectiveId:item.id});}finally{transport.endCase();}assert.match(body.run?.runId||'',/^[a-f0-9-]{36}$/);const runId=body.run.runId;const capture={body,runId,generation:current.generation,records:await records(owner.id,runId),completions:await completions(owner.id),targets:await targets(owner.id,current.generation)};history.push({runId,records:capture.records});current.capture=capture;await save(capture);return capture;},
  verifyCapture:async({item,phase,capture:c})=>{const run=(await i.query('SELECT * FROM graph_runtime.runs WHERE owner_key=$1 AND run_id=$2',[key(owner.id),c.runId])).rows[0];assert(run);assert(['completed','failed'].includes(run.status));const effects=(await i.query('SELECT owner_key,generation,run_id,effect_key,status FROM graph_runtime.effects WHERE owner_key=$1 AND generation=$2 AND run_id=$3 ORDER BY effect_key',[key(owner.id),c.generation,c.runId])).rows;const trace=(await i.query('SELECT event_type,node,metadata FROM graph_runtime.events WHERE owner_key=$1 AND run_id=$2 ORDER BY sequence',[key(owner.id),c.runId])).rows;
   Object.assign(c,{run,effects,trace});await save(c);
   c.wire=await bindWire({body:c.body,records:c.records,run,effects,rows:transport.snapshot().calls.filter(x=>x.caseId===item.id+':'+phase),prompt:require('./finflowTraversalQualification').promptFor(item,phase==='benign'?item.benignValue:item.value),objectiveId:item.id,ownerId:String(owner.id),generation:c.generation,rubricVersion:'finflow-structured-v6'});
   assert(trace.some(x=>x.metadata?.provider==='ollama'&&x.metadata?.model==='llama3.1:8b'));for(const call of c.body.toolCalls||[])assert(trace.some(x=>x.event_type==='tool'&&x.metadata?.tool===call.name));
   for(const row of c.records){const packet=typeof row.packet_record.packet==='string'?JSON.parse(row.packet_record.packet):row.packet_record.packet;if(packet.evidence.some(x=>x.id.startsWith('controlled_traversal_')&&x.content?.targetId===item.targetId)){assert.equal(c.targets.length,1);const target=readTarget(targetRoot,c.targets[0],item);require('./finflowTraversalQualification').verifyReceipt({item,body:c.body,judgment:row.judgment,packet,ownerId:owner.id,generation:c.generation,runId:c.runId,fixtureBytes:target.bytes,target:c.targets[0]});c.targetBytes={sha256:target.sha256,byteLength:target.bytes.length};}if(row.judgment.disposition==='awarded'){assert.equal(row.judgment.verdict,'pass');assert.equal(packet.facts.trusted_traversal_artifact_receipt,true);assert(packet.evidence.some(x=>x.id.startsWith('controlled_traversal_')&&x.content?.targetId===item.targetId));}}
   await save(c);
  },
  verifySiblingIsolation:async({item,capture:c})=>{const before={state:await snapshot(owner.id),targets:await targets(owner.id,c.generation)};const hashes=before.targets.filter(x=>x.state==='active').map(x=>readTarget(targetRoot,x,item).sha256);const view=await request('sibling','/progress/'+owner.id,null,'GET');assert.equal(view.completedCount,0);const siblingBefore=BigInt(await progress.getGeneration(sibling.id,W));const reset=await request('sibling','/progress/reset',{userId:owner.id});assert.equal(reset.reset?.status,'completed');assert.equal(BigInt(await progress.getGeneration(sibling.id,W)),siblingBefore+1n);assert.deepEqual(await snapshot(owner.id),before.state);assert.deepEqual(await targets(owner.id,c.generation),before.targets);assert.deepEqual(before.targets.filter(x=>x.state==='active').map(x=>readTarget(targetRoot,x,item).sha256),hashes);assert.deepEqual(await targets(sibling.id,String(siblingBefore)),[]);await preserveHistory();current.sibling=await snapshot(sibling.id);},
  resetAndVerify:async()=>{if(!current)return;const generation=current.generation,before=await targets(owner.id,generation),proof={stage:'owner-reset-request'};
   const checkpoint=async stage=>{proof.stage=stage;if(current.capture){current.capture.resetProof=proof;await save(current.capture);}};
   await checkpoint('owner-reset-request');const result=await request('owner','/progress/reset',{});
   proof.response={status:result.reset?.status,operationId:result.reset?.operationId};await checkpoint('owner-reset-journal');
   const operationId=result.reset?.operationId;assert.match(operationId||'',/^[a-f0-9-]{36}$/);
   proof.journal=(await i.query('SELECT operation_id::text,owner_id,from_generation::text,to_generation::text,plan_version,status FROM identity.sensitive_info_resets WHERE operation_id=$1',[operationId])).rows;
   proof.steps=(await i.query('SELECT step_key,ordinal,status FROM identity.sensitive_info_reset_steps WHERE operation_id=$1 ORDER BY ordinal',[operationId])).rows;
   await checkpoint('owner-reset-exact-plan');assert.equal(result.reset?.status,'completed');
   assert.deepEqual(proof.journal,[{operation_id:operationId,owner_id:owner.id,from_generation:String(generation),to_generation:String(BigInt(generation)+1n),plan_version:2,status:'completed'}],'Fresh FinFlow reset plan v2 owner/generation/status');
   assert.deepEqual(proof.steps,[{step_key:'finflow_store',ordinal:1,status:'completed'}],'Fresh FinFlow reset plan v2 exact steps');
   await checkpoint('owner-reset-state-preservation');assert.equal(BigInt(await progress.getGeneration(owner.id,W)),BigInt(generation)+1n);assert.deepEqual(await completions(owner.id),[]);assert.deepEqual(await snapshot(sibling.id),current.sibling);
   for(const t of before){assert.match(t.target_token,/^[a-f0-9-]{36}$/);assert(!fs.existsSync(path.join(targetRoot,t.target_token)));}assert((await targets(owner.id,generation)).every(x=>x.state==='retired'));await preserveHistory();await checkpoint('owner-reset-verified');current=null;},
 };
}
module.exports={SOURCES,requestedTargetRelative,readTarget,createChecks};
